// The installer, written in this repository rather than generated by an
// installer tool.
//
// RBLXSetup.exe sits inside a packaged folder and takes it from there: it copies
// the build to a per-user location, records what it installed as manifest.json
// (the same document the updater diffs against, so an installed copy can update
// and uninstall itself file by file), puts Play on the Start menu and the
// desktop, registers itself under Add/Remove Programs, and can remove all of it
// again. The folder layout is preserved because the executables resolve
// shaders/, web/ and games/ relative to where they run.
//
// Usage:
//   RBLXSetup                       install this folder for the current user
//   RBLXSetup --dir <folder>        install somewhere else
//   RBLXSetup --url <manifest.json> where the installed copy should look for updates
//   RBLXSetup --no-shortcuts        install without menu or desktop entries
//   RBLXSetup --launch              start the game when the install finishes
//   RBLXSetup --uninstall           remove the files it installed, keep the data
//   RBLXSetup --uninstall --purge   remove the folder as well
//
// Shortcuts and the uninstall entry are the platform's job: COM's IShellLink and
// HKCU on Windows, a .desktop file on everything else. Nothing here needs a
// network: the payload is the folder the setup was run from.

#include "Updater.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <iostream>
#include <string>
#include <vector>

#ifdef _WIN32
    #ifndef WIN32_LEAN_AND_MEAN
        #define WIN32_LEAN_AND_MEAN
    #endif
    #include <windows.h>
    #include <objbase.h>
    #include <process.h>
    #include <shlobj.h>
#else
    #include <unistd.h>
#endif

namespace {

namespace fs = std::filesystem;

const char* const kProductName = "RBLX Clone";
const char* const kUninstallKey = "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\RBLXClone";

struct Options {
    std::string directory;
    std::string updateUrl;
    bool uninstall = false;
    bool purge = false;
    bool shortcuts = true;
    bool launch = false;
    bool quiet = false;
    bool help = false;
};

void print(const Options& options, const std::string& text) {
    if (!options.quiet) std::cout << text << std::endl;
}

void printError(const std::string& text) { std::cerr << "RBLXSetup: " << text << std::endl; }

void usage() {
    std::cout << "RBLXSetup - installs RBLX Clone for the current user\n\n"
                 "  RBLXSetup [--dir <folder>] [--url <manifest.json>] [--no-shortcuts] [--launch]\n"
                 "  RBLXSetup --uninstall [--dir <folder>] [--purge]\n\n"
                 "Installs the folder this program is in, keeps its layout, and records it\n"
                 "as manifest.json so RBLXUpdater can update or remove it file by file.\n"
                 "Run it from a packaged folder; it refuses to install into itself.\n";
}

std::string executablePath(const char* argv0) {
    std::error_code error;
    const fs::path path = fs::weakly_canonical(fs::absolute(fs::path(argv0 ? argv0 : "."), error), error);
    if (error) return std::string();
    return path.string();
}

std::string executableDirectory(const char* argv0) {
    const std::string path = executablePath(argv0);
    if (path.empty()) return std::string(".");
    std::error_code error;
    const fs::path parent = fs::path(path).parent_path();
    return parent.empty() ? std::string(".") : parent.string();
}

std::string homeDirectory() {
    const char* home = std::getenv("HOME");
#ifdef _WIN32
    if (!home) home = std::getenv("USERPROFILE");
#endif
    return home ? std::string(home) : std::string(".");
}

#ifdef _WIN32

std::wstring widen(const std::string& text) {
    if (text.empty()) return std::wstring();
    const int size = MultiByteToWideChar(CP_UTF8, 0, text.c_str(), static_cast<int>(text.size()),
                                         nullptr, 0);
    if (size <= 0) return std::wstring();
    std::wstring wide(static_cast<std::size_t>(size), L'\0');
    MultiByteToWideChar(CP_UTF8, 0, text.c_str(), static_cast<int>(text.size()), wide.data(), size);
    return wide;
}

std::string narrow(const std::wstring& text) {
    if (text.empty()) return std::string();
    const int size = WideCharToMultiByte(CP_UTF8, 0, text.c_str(), static_cast<int>(text.size()),
                                         nullptr, 0, nullptr, nullptr);
    if (size <= 0) return std::string();
    std::string narrowed(static_cast<std::size_t>(size), '\0');
    WideCharToMultiByte(CP_UTF8, 0, text.c_str(), static_cast<int>(text.size()), narrowed.data(), size,
                        nullptr, nullptr);
    return narrowed;
}

std::string knownFolder(int csidl) {
    wchar_t path[MAX_PATH] = {};
    if (FAILED(SHGetFolderPathW(nullptr, csidl | CSIDL_FLAG_CREATE, nullptr, SHGFP_TYPE_CURRENT, path))) {
        return std::string();
    }
    return narrow(path);
}

std::string defaultInstallDirectory() {
    const std::string local = knownFolder(CSIDL_LOCAL_APPDATA);
    if (local.empty()) return std::string();
    return (fs::path(local) / "RBLXClone").string();
}

bool createShortcut(const std::string& linkPath, const std::string& target,
                    const std::string& arguments, const std::string& workingDirectory,
                    const std::string& description) {
    IShellLinkW* link = nullptr;
    if (FAILED(CoCreateInstance(CLSID_ShellLink, nullptr, CLSCTX_INPROC_SERVER, IID_IShellLinkW,
                                reinterpret_cast<void**>(&link)))) {
        return false;
    }

    link->SetPath(widen(target).c_str());
    link->SetArguments(widen(arguments).c_str());
    link->SetWorkingDirectory(widen(workingDirectory).c_str());
    link->SetDescription(widen(description).c_str());

    IPersistFile* file = nullptr;
    bool saved = false;
    if (SUCCEEDED(link->QueryInterface(IID_IPersistFile, reinterpret_cast<void**>(&file)))) {
        saved = SUCCEEDED(file->Save(widen(linkPath).c_str(), TRUE));
        file->Release();
    }
    link->Release();
    return saved;
}

bool setString(HKEY key, const wchar_t* name, const std::string& value) {
    const std::wstring wide = widen(value);
    return RegSetValueExW(key, name, 0, REG_SZ, reinterpret_cast<const BYTE*>(wide.c_str()),
                          static_cast<DWORD>((wide.size() + 1) * sizeof(wchar_t))) == ERROR_SUCCESS;
}

bool registerUninstall(const std::string& installDirectory, const std::string& version) {
    HKEY key = nullptr;
    if (RegCreateKeyExW(HKEY_CURRENT_USER, widen(kUninstallKey).c_str(), 0, nullptr, 0, KEY_WRITE,
                        nullptr, &key, nullptr) != ERROR_SUCCESS) {
        return false;
    }

    const std::string setup = (fs::path(installDirectory) / "RBLXSetup.exe").string();
    bool ok = setString(key, L"DisplayName", kProductName);
    ok = ok && setString(key, L"DisplayVersion", version);
    ok = ok && setString(key, L"Publisher", kProductName);
    ok = ok && setString(key, L"InstallLocation", installDirectory);
    ok = ok && setString(key, L"DisplayIcon", (fs::path(installDirectory) / "Client.exe").string());
    ok = ok && setString(key, L"UninstallString", "\"" + setup + "\" --uninstall");
    ok = ok && setString(key, L"QuietUninstallString", "\"" + setup + "\" --uninstall --quiet");

    // Add/Remove Programs offers Modify and Repair unless told otherwise, and
    // this install has neither.
    const DWORD one = 1;
    RegSetValueExW(key, L"NoModify", 0, REG_DWORD, reinterpret_cast<const BYTE*>(&one), sizeof(one));
    RegSetValueExW(key, L"NoRepair", 0, REG_DWORD, reinterpret_cast<const BYTE*>(&one), sizeof(one));

    RegCloseKey(key);
    return ok;
}

bool unregisterUninstall() {
    // SHDeleteKey rather than RegDeleteTree: the latter needs a Win32 version
    // macro, and this project does not set one.
    SHDeleteKeyW(HKEY_CURRENT_USER, widen(kUninstallKey).c_str());
    return true;
}

bool removeShortcuts(const Options& options) {
    (void)options;
    const std::string programs = knownFolder(CSIDL_PROGRAMS);
    if (!programs.empty()) {
        std::error_code code;
        fs::remove_all(fs::path(programs) / kProductName, code);
    }
    const std::string desktop = knownFolder(CSIDL_DESKTOPDIRECTORY);
    if (!desktop.empty()) {
        std::error_code code;
        fs::remove(fs::path(desktop) / (std::string(kProductName) + ".lnk"), code);
    }
    return true;
}

bool createShortcuts(const std::string& installDirectory, const Options& options) {
    (void)options;
    const std::string updater = (fs::path(installDirectory) / "RBLXUpdater.exe").string();
    const std::string setup = (fs::path(installDirectory) / "RBLXSetup.exe").string();

    const std::string programs = knownFolder(CSIDL_PROGRAMS);
    bool ok = !programs.empty();
    if (ok) {
        const fs::path menu = fs::path(programs) / kProductName;
        std::error_code code;
        fs::create_directories(menu, code);
        // Play goes through the updater, which checks for a release before
        // starting the client.
        ok = createShortcut((menu / "Play RBLX Clone.lnk").string(), updater, "--launch", installDirectory,
                            "Checks for updates, then starts RBLX Clone") &&
             ok;
        ok = createShortcut((menu / "RBLX Clone website.lnk").string(),
                            (fs::path(installDirectory) / "start-website.bat").string(), "", installDirectory,
                            "Starts the local RBLX website") &&
             ok;
        ok = createShortcut((menu / "Uninstall RBLX Clone.lnk").string(), setup, "--uninstall",
                            installDirectory, "Removes RBLX Clone from this account") &&
             ok;
    }

    const std::string desktop = knownFolder(CSIDL_DESKTOPDIRECTORY);
    if (!desktop.empty()) {
        ok = createShortcut((fs::path(desktop) / (std::string(kProductName) + ".lnk")).string(), updater,
                            "--launch", installDirectory, "Checks for updates, then starts RBLX Clone") &&
             ok;
    }
    return ok;
}

bool initializeCom() {
    return SUCCEEDED(CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED));
}

void uninitializeCom() { CoUninitialize(); }

#else  // not Windows: a desktop entry is the equivalent of the menu shortcut.

std::string defaultInstallDirectory() {
    return (fs::path(homeDirectory()) / ".local/share/rblx-clone").string();
}

std::string applicationsDirectory() {
    const char* data = std::getenv("XDG_DATA_HOME");
    if (data && *data) return (fs::path(data) / "applications").string();
    return (fs::path(homeDirectory()) / ".local/share/applications").string();
}

bool createShortcuts(const std::string& installDirectory, const Options& options) {
    (void)options;
    const std::string text =
        std::string("[Desktop Entry]\nType=Application\nName=") + kProductName +
        "\nComment=Checks for updates, then starts RBLX Clone\nExec=\"" + installDirectory +
        "/RBLXUpdater\" --launch\nPath=" + installDirectory +
        "\nTerminal=false\nCategories=Game;\n";

    std::string error;
    const fs::path path = fs::path(applicationsDirectory()) / "rblx-clone.desktop";
    return rblx::update::writeFileAtomically(path.string(), text, &error);
}

bool removeShortcuts(const Options& options) {
    (void)options;
    std::error_code code;
    fs::remove(fs::path(applicationsDirectory()) / "rblx-clone.desktop", code);
    return true;
}

bool initializeCom() { return true; }
void uninitializeCom() {}

#endif

bool copyFile(const fs::path& from, const fs::path& to, std::string* error) {
    std::string data;
    if (!rblx::update::readTextFile(from.string(), &data)) {
        if (error) *error = "could not read " + from.string();
        return false;
    }
    if (!rblx::update::writeFileAtomically(to.string(), data, error)) return false;

    // A copied binary has to stay executable: on POSIX the install ships real
    // executables, and writeFileAtomically creates ordinary files.
    std::error_code code;
    const fs::perms permissions = fs::status(from, code).permissions();
    if (!code) fs::permissions(to, permissions, fs::perm_options::replace, code);
    return true;
}

// Copies the release payload, leaving a file alone when the installed copy is
// already identical. User data (accounts, worlds, logs) is never in the payload,
// so an install over an existing folder keeps it.
bool copyPayload(const std::string& source, const std::string& target, int* copied, int* skipped,
                 std::string* error) {
    std::vector<std::string> files;
    if (!rblx::update::collectPayloadFiles(source, &files, error)) return false;

    for (const std::string& relative : files) {
        const fs::path from = fs::path(source) / relative;
        const fs::path to = fs::path(target) / relative;

        std::error_code code;
        if (fs::exists(to, code)) {
            const auto fromSize = fs::file_size(from, code);
            const auto toSize = fs::file_size(to, code);
            if (!code && fromSize == toSize) {
                std::string ignored;
                if (rblx::update::sha256File(from.string(), &ignored) ==
                    rblx::update::sha256File(to.string(), &ignored)) {
                    ++*skipped;
                    continue;
                }
            }
        }

        if (!copyFile(from, to, error)) return false;
        ++*copied;
    }
    return true;
}

std::string readVersion(const std::string& directory) {
    rblx::update::Manifest manifest;
    std::string error;
    const fs::path path = fs::path(directory) / "manifest.json";
    if (rblx::update::readManifestFile(path.string(), &manifest, &error) && !manifest.version.empty()) {
        return manifest.version;
    }
    return "0.0.0";
}

int install(const Options& options, const std::string& source) {
    if (source.empty()) {
        printError("could not work out which folder this setup is running from");
        return 1;
    }

    const std::string target = options.directory.empty() ? defaultInstallDirectory() : options.directory;
    if (target.empty()) {
        printError("could not find a home folder to install into; pass --dir");
        return 1;
    }

    std::error_code code;
    if (fs::equivalent(fs::weakly_canonical(source, code), fs::weakly_canonical(target, code), code)) {
        printError("this folder is already installed here; run RBLXSetup from a package, not from an install");
        return 1;
    }

    if (!rblx::update::collectPayloadFiles(source, nullptr, nullptr)) {
        printError("there is nothing to install in " + source);
        return 1;
    }

    const std::string version = readVersion(source);
    print(options, "installing " + std::string(kProductName) + " " + version + " into " + target);

    // Everything below writes into the target; creating it first turns a typo in
    // --dir into an empty folder rather than a half-made install.
    fs::create_directories(target, code);
    if (code) {
        printError("could not create " + target + ": " + code.message());
        return 1;
    }

    std::string error;
    int copied = 0;
    int skipped = 0;
    if (!copyPayload(source, target, &copied, &skipped, &error)) {
        printError(error);
        return 1;
    }
    print(options, "  " + std::to_string(copied) + " file(s) written, " + std::to_string(skipped) +
                       " already up to date");

    // The settings that say where this copy looks for updates. An explicit --url
    // wins; otherwise the package's own update.json is carried over, and an
    // existing install keeps the one it has.
    const fs::path targetConfig = fs::path(target) / "update.json";
    if (!options.updateUrl.empty()) {
        rblx::update::Config config;
        config.manifestUrl = options.updateUrl;
        if (!rblx::update::writeConfigFile(targetConfig.string(), config, &error)) {
            printError(error);
            return 1;
        }
        print(options, "  updates will be checked at " + options.updateUrl);
    } else if (!fs::exists(targetConfig, code)) {
        const fs::path sourceConfig = fs::path(source) / "update.json";
        if (fs::exists(sourceConfig, code)) {
            if (!copyFile(sourceConfig, targetConfig, &error)) {
                printError(error);
                return 1;
            }
        } else {
            print(options, "  no update.json: this copy will not look for updates until one is written");
        }
    }

    // The installed manifest is what the updater diffs against and what the
    // uninstaller removes from. The package ships one; a folder built by hand does
    // not, so it is generated here from what was actually copied.
    const fs::path targetManifest = fs::path(target) / "manifest.json";
    rblx::update::Manifest manifest;
    const bool packaged = rblx::update::readManifestFile((fs::path(source) / "manifest.json").string(),
                                                         &manifest, &error);
    if (!packaged &&
        !rblx::update::buildManifestFromDirectory(source, version, "stable", &manifest, &error)) {
        printError(error);
        return 1;
    }
    if (!rblx::update::writeManifestFile(targetManifest.string(), manifest, &error)) {
        printError(error);
        return 1;
    }
    print(options, "  recorded " + std::to_string(manifest.files.size()) +
                       " file(s) in manifest.json for updates and uninstall");

    // The updater and the setup are deliberately not in the release manifest (the
    // updater cannot replace the copy that is running it), so the install carries
    // them over by name. The setup travels with the install because it is the
    // uninstaller: it removes this exact copy file by file, and running it again
    // reinstalls or upgrades in place.
#ifdef _WIN32
    const char* const programs[] = {"RBLXUpdater.exe", "RBLXSetup.exe"};
#else
    const char* const programs[] = {"RBLXUpdater", "RBLXSetup"};
#endif
    for (const char* program : programs) {
        const fs::path from = fs::path(source) / program;
        if (!fs::exists(from)) continue;
        if (!copyFile(from, fs::path(target) / program, &error)) {
            printError(error);
            return 1;
        }
    }

    if (options.shortcuts) {
        if (createShortcuts(target, options)) {
            print(options, "  added the Play shortcut");
        } else {
            printError("could not add the shortcuts; the install itself is complete");
        }
    }

#ifdef _WIN32
    const bool registered = registerUninstall(target, version);
    if (registered) {
        print(options, "  registered in Add/Remove Programs");
    } else {
        printError("could not register the uninstall entry; the install itself is complete");
    }
#endif

    print(options, "installed; start it with " + target);
    return 0;
}

int uninstall(const Options& options, const char* argv0) {
    // The setup lives in the folder it installed, and that is how Add/Remove
    // Programs runs it ("<dir>\RBLXSetup.exe" --uninstall), so the folder this
    // program is in is the one to remove. --dir overrides it for a copy that was
    // moved somewhere else.
    const std::string target = options.directory.empty() ? executableDirectory(argv0) : options.directory;
    if (target.empty()) {
        printError("could not find the install folder; pass --dir");
        return 1;
    }

    rblx::update::Manifest manifest;
    std::string error;
    const fs::path manifestPath = fs::path(target) / "manifest.json";
    if (!rblx::update::readManifestFile(manifestPath.string(), &manifest, &error)) {
        printError(error);
        return 1;
    }

    print(options, "removing " + std::string(kProductName) + " from " + target);

    int removed = 0;
    std::error_code code;
    for (const rblx::update::FileEntry& entry : manifest.files) {
        std::string resolved;
        if (!rblx::update::resolveUnder(target, entry.path, &resolved)) continue;
        if (fs::remove(resolved, code)) ++removed;
    }

    // Files the release does not describe but the install owns: the settings, the
    // manifest, and the two programs that are not part of the payload. A binary
    // that is running cannot delete itself on Windows, so it is renamed instead;
    // on POSIX it simply goes.
    for (const char* name : {"manifest.json", "update.json", "RBLXUpdater", "RBLXUpdater.exe",
                             "RBLXSetup", "RBLXSetup.exe"}) {
        const fs::path path = fs::path(target) / name;
        std::error_code removeError;
        if (!fs::remove(path, removeError) && fs::exists(path, removeError)) {
            std::error_code renameError;
            fs::rename(path, fs::path(path.string() + ".old"), renameError);
        }
    }

    removeShortcuts(options);
#ifdef _WIN32
    unregisterUninstall();
#endif

    if (options.purge) {
        fs::remove_all(target, code);
        print(options, "removed the folder, including worlds and account data");
    } else {
        // Empty folders left behind by removed files go too; anything with user
        // data in it stays.
        std::vector<fs::path> folders;
        for (fs::recursive_directory_iterator it(target,
                                                 fs::directory_options::skip_permission_denied, code),
             end;
             it != end; it.increment(code)) {
            if (code) break;
            if (it->is_directory(code)) folders.push_back(it->path());
        }
        std::sort(folders.begin(), folders.end(), [](const fs::path& a, const fs::path& b) {
            return a.string().size() > b.string().size();
        });
        for (const fs::path& folder : folders) {
            std::error_code ignored;
            if (fs::is_empty(folder, ignored)) fs::remove(folder, ignored);
        }
        print(options, "removed " + std::to_string(removed) +
                           " file(s); worlds, saves and account data are still there. "
                           "Run it with --purge to delete those too.");
    }
    return 0;
}

bool parseOptions(int argc, char** argv, Options* options) {
    for (int i = 1; i < argc; ++i) {
        const std::string argument = argv[i];
        if (argument == "--dir" && i + 1 < argc) {
            options->directory = argv[++i];
        } else if (argument == "--url" && i + 1 < argc) {
            options->updateUrl = argv[++i];
        } else if (argument == "--uninstall") {
            options->uninstall = true;
        } else if (argument == "--purge") {
            options->purge = true;
        } else if (argument == "--no-shortcuts") {
            options->shortcuts = false;
        } else if (argument == "--launch") {
            options->launch = true;
        } else if (argument == "--quiet") {
            options->quiet = true;
        } else if (argument == "--help" || argument == "-h") {
            options->help = true;
        } else {
            printError("unknown option " + argument);
            usage();
            return false;
        }
    }
    return true;
}

}  // namespace

int main(int argc, char** argv) {
    Options options;
    if (!parseOptions(argc, argv, &options)) return 2;
    if (options.help) {
        usage();
        return 0;
    }

    const bool com = initializeCom();
    const std::string source = executableDirectory(argv[0]);
    const int status = options.uninstall ? uninstall(options, argv[0]) : install(options, source);

    if (com) uninitializeCom();

    if (status == 0 && options.launch && !options.uninstall) {
        const std::string target =
            options.directory.empty() ? defaultInstallDirectory() : options.directory;
#ifdef _WIN32
        const fs::path updater = fs::path(target) / "RBLXUpdater.exe";
#else
        // The Unix build's executables carry no extension.
        const fs::path updater = fs::path(target) / "RBLXUpdater";
#endif
        if (!fs::exists(updater)) {
            printError("there is no " + updater.string() + " in " + target + " to start");
            return 1;
        }
#ifdef _WIN32
        _spawnl(_P_NOWAIT, updater.string().c_str(), updater.string().c_str(), "--launch",
                static_cast<char*>(nullptr));
#else
        const pid_t pid = fork();
        if (pid == 0) {
            if (chdir(target.c_str()) != 0) _exit(127);
            execl(updater.c_str(), updater.c_str(), "--launch", static_cast<char*>(nullptr));
            _exit(127);
        }
#endif
    }
    return status;
}
